-- =====================================================================
-- seed/design/70_donation.sql : blood donors, donations, requests, blood banks + stock,
--   camps + pledges, organ pledge (Anjali), next of kin, witnesses, transplant centres,
--   waiting-list snapshots, coordinators and a lookup log row.
-- Kinds 0701-0714 (ids cfd00000-KKKK-4000-8000-NNNNNNNNNNNN). Idempotent (ON CONFLICT DO NOTHING).
-- Runs after migrations 000-128 and 00_base.sql. Synthetic data only, no Aadhaar digits.
-- Demo "today" = Saturday 17 October 2026, times IST (+05:30).
--
-- Decisions (see the report for the conflicts they settle):
--   * Anjali: last donation 4 Aug 2026 (not 02 Aug); eligible again 2 Nov 2026; 7 donations since 2019;
--     age 35, weight 61 kg (IDS D1 and the suggested values).
--   * The prototype's "Silver donor" tier does not exist in v_donor_summary (7 donations = bronze).
--   * Mother is Sarala Nair (D7); witness 2 is Johnson Kuruvilla (D3). Johnson has signed (15 Oct),
--     Sarala's link is still open (expires 24 Oct): "1 of 2 signed" = 50 percent.
--   * Dates in the prototype carry 2025 weekdays; the dates are kept and weekdays follow 2026
--     (22 Oct 2026 is a Thursday, 26 Oct a Monday, 8 Nov a Sunday).
--   * Blood stock: the group totals and days of cover of the admin consoles are exact for the
--     Pathanamthitta district (1,162 units over 5 banks) and for Kerala (17,051 units). The bank
--     table of the district console shows 466 / 303 / 211 / 123 + 59 (Demo General Hospital)
--     instead of 486 / 318 / 221 / 137 because the DGH bank has to be part of the 1,162 too.
--   * Zone / national blood stock cannot be seeded: only Kerala has geo.district rows.
--     Waiting lists and centres are state-level, so they ARE seeded for all 36 states and UTs.
-- Triggers: blood_donation_apply is disabled for the donation inserts so the donors keep their
--   `ready` flags; blood_donor rows are inserted with the values the trigger would have produced.
-- =====================================================================
BEGIN;

-- ---------- extra blood banks (kind 0701); banks 0017-1 and 0017-2 come from the base ----------
ON CONFLICT DO NOTHING;

-- ---------- blood stock readings (kind 0702): latest 17 Oct 14:00 + history for the cover views ----------
ON CONFLICT DO NOTHING;

-- ---------- blood camps (kind 0705) ----------
ON CONFLICT DO NOTHING;

-- camp pledges: Anjali is resting until 2 Nov and has not pledged yet (the demo can do it live).
ON CONFLICT DO NOTHING;

-- ---------- blood donors and donations ----------
ALTER TABLE donation.blood_donation DISABLE TRIGGER blood_donation_apply;
ON CONFLICT DO NOTHING;
ALTER TABLE donation.blood_donation ENABLE TRIGGER blood_donation_apply;

-- donor profiles (what the apply_donation trigger would have written, plus the ready flags)
ON CONFLICT DO NOTHING;
-- keep the donor-code sequence ahead of the seeded codes (a new real donor gets 30441 or higher)
SELECT setval('donation.donor_code_seq', greatest((SELECT last_value FROM donation.donor_code_seq), 30440));

-- Anjali's "eligible again" date for the Dates calendar (what the trigger writes for a donation)
ON CONFLICT DO NOTHING;

-- ---------- pre-donation checklists (kind 0706) ----------
ON CONFLICT DO NOTHING;

-- ---------- blood requests (kind 0704): 3 open ----------
  -- 1: Demo Medical College, Kottayam, surgery today 18:00 (urgent)
  ('cfd00000-0704-4000-8000-000000000001', 'cfd00000-0002-4000-8000-000000000102', NULL, 'B+', 2, 'cfd00000-0010-4000-8000-000000000008', 'urgent', 'open', '2026-10-17 11:20:00+05:30', '2026-10-17 18:00:00+05:30', '2026-10-17 11:20:00+05:30'),
  -- 2: Demo General Hospital, thalassaemia patient, this week
  ('cfd00000-0704-4000-8000-000000000002', 'cfd00000-0002-4000-8000-000000000104', NULL, 'B+', 1, 'cfd00000-0010-4000-8000-000000000001', 'normal', 'open', '2026-10-15 10:00:00+05:30', '2026-10-23 18:00:00+05:30', '2026-10-15 10:00:00+05:30'),
  -- 3: Demo General Hospital, surgery tomorrow 08:00 (bus event s10, 14:30, from Dr. Arun Nair)
  ('cfd00000-0704-4000-8000-000000000003', 'cfd00000-0002-4000-8000-000000000002', NULL, 'B+', 2, 'cfd00000-0010-4000-8000-000000000001', 'urgent', 'open', '2026-10-17 14:30:00+05:30', '2026-10-18 08:00:00+05:30', '2026-10-17 14:30:00+05:30')
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;

-- ---------- organ pledge (kinds 0707-0709): Anjali, step 3 of 4 "sign at hospital" ----------
VALUES ('cfd00000-0707-4000-8000-000000000001', 'cfd00000-0001-4000-8000-000000000001', ARRAY['kidneys','corneas'], '2026-10-09 19:30:00+05:30', 'cfd00000-0010-4000-8000-000000000001', NULL, NULL, 'pending', 'signing', '2026-10-12 10:15:00+05:30', 'not_sent')
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;

-- ---------- transplant centres (kind 0711): Kerala 26 (with the base centre), South zone 214, India 812 ----------
ON CONFLICT DO NOTHING;

-- ---------- waiting-list snapshots (kind 0712): all states on 17 Oct 2026, Kerala also 17 Sep and 17 Aug ----------
ON CONFLICT DO NOTHING;

-- ---------- transplant coordinators (restricted lookup) and one past lookup (kinds 0714) ----------
ON CONFLICT DO NOTHING;
-- The person is a filler citizen of demo_data.sql (no base person is deceased in the stories).
SELECT 'cfd00000-0714-4000-8000-000000000001', 'cfd00000-0002-4000-8000-000000000103', p.id, 'DEMO-BSD-KL-2026-0117', 'Brain-stem death certified by the board; checking for a registered pledge before counselling the family.', '2026-09-02 05:40:00+05:30'
FROM identity.person p WHERE p.id::text NOT LIKE 'cfd00000-%' ORDER BY p.created_at, p.id LIMIT 1
ON CONFLICT DO NOTHING;

COMMIT;
